import { XMLParser } from "fast-xml-parser";

export interface Episode {
  guid: string;
  title: string;
  enclosureUrl: string;
  publishedAt: string;
}

const parser = new XMLParser({ ignoreAttributes: false });

export function parseFeed(xml: string): Episode[] {
  const document = parser.parse(xml) as { rss?: { channel?: { item?: unknown[] } } };
  const items = document.rss?.channel?.item ?? [];
  return dedupe(items.map((item) => item as Episode));
}

/** Identity is the enclosure plus the publish date; hosts rewrite guids freely. */
export function dedupe(episodes: Episode[]): Episode[] {
  const seen = new Set<string>();
  const kept: Episode[] = [];
  for (const episode of episodes) {
    const identity = episode.enclosureUrl + "|" + episode.publishedAt;
    if (seen.has(identity)) continue;
    seen.add(identity);
    kept.push(episode);
  }
  return kept;
}

