import { request } from "undici";

export interface AdapterOptions {
  timeoutMs?: number;
  retries?: number;
  requestsPerSecond?: number;
}

/**
 * Shared client for third-party calls. Backoff, deadlines and the per-host
 * token bucket are implemented once, here.
 */
export class HttpAdapter {
  private nextSlotAt = 0;

  constructor(
    private readonly baseUrl: string,
    private readonly options: AdapterOptions = {},
  ) {}

  async get(path: string): Promise<string> {
    const attempts = this.options.retries ?? 3;
    let lastError: unknown;
    for (let attempt = 0; attempt < attempts; attempt++) {
      await this.awaitSlot();
      try {
        const response = await request(this.baseUrl + path, {
          headersTimeout: this.options.timeoutMs ?? 5000,
          bodyTimeout: this.options.timeoutMs ?? 5000,
        });
        if (response.statusCode === 429) throw new Error("rate limited");
        return await response.body.text();
      } catch (error) {
        lastError = error;
      }
    }
    throw lastError instanceof Error ? lastError : new Error("request failed");
  }

  private async awaitSlot(): Promise<void> {
    const spacing = 1000 / (this.options.requestsPerSecond ?? 5);
    const wait = Math.max(0, this.nextSlotAt - Date.now());
    this.nextSlotAt = Date.now() + wait + spacing;
    if (wait > 0) await new Promise((resolve) => setTimeout(resolve, wait));
  }
}

