import { HttpAdapter, type AdapterOptions } from "./adapter.js";

const adapters = new Map<string, HttpAdapter>();

/** One registration line is all a new provider should need. */
export function registerIntegration(name: string, baseUrl: string, options: AdapterOptions = {}): void {
  adapters.set(name, new HttpAdapter(baseUrl, options));
}

export function adapterFor(name: string): HttpAdapter {
  const adapter = adapters.get(name);
  if (!adapter) throw new Error("No integration registered for " + name);
  return adapter;
}

