export interface RefreshPlan {
  feedId: string;
  nextRunAt: number;
}

const HOUR_MS = 60 * 60 * 1000;

export function planRefresh(feedId: string, subscribed: boolean, now: number): RefreshPlan {
  return { feedId, nextRunAt: now + (subscribed ? HOUR_MS : 24 * HOUR_MS) };
}

/** Nightly warm-up so the morning traffic spike does not pay for cold artwork. */
export function planArtworkWarmup(showIds: string[], now: number): RefreshPlan[] {
  return showIds.slice(0, 500).map((feedId, index) => ({
    feedId,
    nextRunAt: now + index * 200,
  }));
}
